package places

import (
	"bufio"
	"bytes"
	"compress/gzip"
	_ "embed"
	"strconv"
	"strings"
	"sync"
	"unicode"

	"golang.org/x/text/runes"
	"golang.org/x/text/transform"
	"golang.org/x/text/unicode/norm"
)

// City data from GeoNames (CC BY 4.0), generated by tools/gendata.
//
//go:embed data/cities.tsv.gz
var citiesGz []byte

//go:embed data/countries.tsv
var countriesTSV []byte

// City is a populated place with its time zone.
type City struct {
	Name, ASCII, CC, AdminCode, Admin, TZ string
	Pop                                   int
	Alts                                  []string
}

// Country is an ISO country with its capital.
type Country struct {
	ISO2, ISO3, Name, Capital string
}

type database struct {
	cities    []City           // sorted by population, largest first
	byName    map[string][]int // normalized name or ASCII name
	byAlt     map[string][]int // normalized alternate names (big cities only)
	normNames []string         // normalized City.Name, parallel to cities
	countries []Country
	countryBy map[string]int    // iso2, iso3, normalized name, aliases
	zones     map[string]string // lowercased IANA name -> canonical
}

var (
	dbOnce sync.Once
	theDB  *database
)

func db() *database {
	dbOnce.Do(func() { theDB = loadDB() })
	return theDB
}

var countryAliases = map[string]string{
	"america": "US", "united states of america": "US", "states": "US",
	"uk": "GB", "britain": "GB", "great britain": "GB", "england": "GB",
	"scotland": "GB", "wales": "GB", "holland": "NL", "korea": "KR",
	"czech republic": "CZ", "uae": "AE", "emirates": "AE", "turkiye": "TR",
	"russia": "RU", "vatican": "VA", "ivory coast": "CI",
}

func loadDB() *database {
	d := &database{
		byName:    map[string][]int{},
		byAlt:     map[string][]int{},
		countryBy: map[string]int{},
		zones:     map[string]string{},
	}

	zr, err := gzip.NewReader(bytes.NewReader(citiesGz))
	if err != nil {
		panic("places: corrupt city data: " + err.Error())
	}
	sc := bufio.NewScanner(zr)
	sc.Buffer(make([]byte, 1<<16), 1<<20)
	for sc.Scan() {
		f := strings.Split(sc.Text(), "\t")
		if len(f) < 8 {
			continue
		}
		pop, _ := strconv.Atoi(f[5])
		c := City{Name: f[0], ASCII: f[1], CC: f[2], AdminCode: f[3], Admin: f[4], Pop: pop, TZ: f[6]}
		if c.ASCII == "" {
			c.ASCII = c.Name
		}
		if f[7] != "" {
			c.Alts = strings.Split(f[7], "|")
		}
		i := len(d.cities)
		d.cities = append(d.cities, c)
		n := Normalize(c.Name)
		d.normNames = append(d.normNames, n)
		d.byName[n] = append(d.byName[n], i)
		if a := Normalize(c.ASCII); a != n {
			d.byName[a] = append(d.byName[a], i)
		}
		for _, alt := range c.Alts {
			k := Normalize(alt)
			d.byAlt[k] = append(d.byAlt[k], i)
		}
		d.zones[strings.ToLower(c.TZ)] = c.TZ
	}

	for _, line := range strings.Split(string(countriesTSV), "\n") {
		f := strings.Split(line, "\t")
		if len(f) < 4 {
			continue
		}
		i := len(d.countries)
		d.countries = append(d.countries, Country{ISO2: f[0], ISO3: f[1], Name: f[2], Capital: f[3]})
		d.countryBy[strings.ToLower(f[0])] = i
		d.countryBy[strings.ToLower(f[1])] = i
		d.countryBy[Normalize(f[2])] = i
	}
	for alias, iso := range countryAliases {
		if i, ok := d.countryBy[strings.ToLower(iso)]; ok {
			d.countryBy[alias] = i
		}
	}
	return d
}

var stripMarks = transform.Chain(norm.NFD, runes.Remove(runes.In(unicode.Mn)), norm.NFC)

// Normalize lowercases, strips accents and treats '_' like a space, so
// "São_Paulo" and "sao paulo" compare equal.
func Normalize(s string) string {
	for i := 0; i < len(s); i++ {
		if s[i] >= 0x80 {
			s, _, _ = transform.String(stripMarks, s)
			break
		}
	}
	s = strings.ToLower(strings.ReplaceAll(s, "_", " "))
	return strings.Join(strings.Fields(s), " ")
}

func (d *database) country(cc string) (Country, bool) {
	i, ok := d.countryBy[strings.ToLower(cc)]
	if !ok {
		return Country{}, false
	}
	return d.countries[i], true
}

// cityPlace describes a city the way worldtimebuddy does: "Salt Lake City" /
// "United States, Utah".
func (d *database) cityPlace(c City) Place {
	sub := c.CC
	if k, ok := d.country(c.CC); ok {
		sub = k.Name
	}
	switch c.CC {
	case "US", "CA", "AU":
		if c.Admin != "" {
			sub += ", " + c.Admin
		}
	}
	return Place{Name: c.Name, Sub: sub, TZ: c.TZ}
}
